import { ChannelOptions } from 'nice-grpc';
export { ChannelOptions as GrpcChannelOptions } from 'nice-grpc';

/**
 * Core streaming primitive used by every server-streaming SDK method.
 *
 * Wraps an async iterable source (typically from a gRPC server-streaming RPC)
 * Exposes `for await`, `.on()`, `.filter()`, `.map()`, `.take()`, `.close()`,
 * and `Symbol.asyncDispose`.
 *
 * Only one consumer is allowed per stream instance. Calling `.on()` or
 * iterating a stream that is already being consumed throws an error.
 * Use `.filter()` / `.map()` / `.take()` to derive new streams before
 * consuming them.
 */
declare class TypedEventStream<T> implements AsyncIterable<T>, AsyncDisposable {
    /** The underlying async iterable source. */
    private readonly _source;
    /** Optional cleanup callback invoked when the stream is closed. */
    private readonly _cleanup;
    /** Whether this stream has been closed. */
    private _closed;
    /** Whether a consumer has already attached to this stream. */
    private _consumed;
    /**
     * When a consumer is blocked on `next()`, this resolver lets `.close()`
     * interrupt it immediately.
     */
    private _cancelResolve;
    constructor(source: AsyncIterable<T>, cleanup?: () => Promise<void>);
    [Symbol.asyncIterator](): AsyncIterator<T>;
    /**
     * Subscribe to events with a callback. Returns an unsubscribe function that
     * stops the internal consumption loop.
     *
     * The callback may be synchronous or async. If async, back-pressure is
     * applied -- the next event is not delivered until the previous callback
     * resolves. Pass `onError` to handle callback or source errors; otherwise
     * errors are rethrown on the next microtask.
     */
    on(callback: (event: T) => void | Promise<void>, onError?: (error: unknown) => void): () => void;
    /**
     * Create a filtered sub-stream. When the predicate is a type-guard the
     * returned stream is narrowed to the guard type.
     */
    filter<S extends T>(predicate: (event: T) => event is S): TypedEventStream<S>;
    filter(predicate: (event: T) => boolean): TypedEventStream<T>;
    /** Transform each event into a different shape. */
    map<U>(transform: (event: T) => U): TypedEventStream<U>;
    /**
     * Yield the first `count` events, then close the parent stream.
     *
     * `count <= 0` returns an empty stream without consuming the parent.
     */
    take(count: number): TypedEventStream<T>;
    /** Signal the stream is done. Interrupts any pending iteration. */
    close(): Promise<void>;
    /** `Symbol.asyncDispose` -- enables `await using`. */
    [Symbol.asyncDispose](): Promise<void>;
    /**
     * Claim sole-consumer rights. Throws if the stream has already been
     * consumed or closed.
     */
    private _claimConsumer;
    /**
     * Internal async generator that pulls from the source and respects the
     * closed flag.
     */
    private _iterate;
    /**
     * Returns a promise that resolves to `undefined` when `.close()` is called.
     * If the stream is already closed, resolves immediately.
     */
    private _cancelPromise;
}

/**
 * Shared types used across multiple resource namespaces.
 */
/** Options for automatic retry with exponential back-off. */
interface RetryOptions {
    /** Initial delay in milliseconds before the first retry. */
    readonly initialDelay?: number;
    /** Maximum number of attempts (including the initial call). */
    readonly maxAttempts?: number;
    /** Maximum delay in milliseconds between retries. */
    readonly maxDelay?: number;
}
/** Caller-provided key that lets the server deduplicate retries. */
interface IdempotencyOptions {
    /** Stable key for one logical write. Reuse it only when retrying that same write. */
    readonly clientMessageId?: string;
}
/**
 * Invoked once for every server heartbeat frame received on any
 * `subscribeEvents` / `watch` stream.
 *
 * The server emits heartbeats on a fixed cadence (~30s) even when no domain
 * events occur. Consumers can use this signal to run a stall watchdog: if no
 * heartbeat arrives within a grace window, the connection is likely half-open
 * and the stream should be torn down and re-established. Without this hook the
 * heartbeat frames are silently dropped and a half-open stall is undetectable
 * from the event stream alone.
 */
type HeartbeatHandler = () => void;

/**
 * Lightweight string-union enums for the SDK's public API.
 *
 * These replace the generated protobuf numeric enums with human-readable
 * string literals. The mapper layer handles conversion to/from wire values.
 */
/** Current transfer state of an attachment. */
type TransferState = "pending" | "transferring" | "failed" | "finished" | "unknown";
/** Discriminates the kind of item a message represents. */
type MessageItemType = "normal" | "groupNameChange" | "participantChange" | "chatAction" | "unknown";
/** The underlying transport service for a chat or address. */
type ChatServiceType = "iMessage" | "SMS" | "RCS" | "unknown";
/** Sidecar attachment kind. */
type CompanionKind = "live-photo-video" | "unknown";

/**
 * Address-related domain types.
 */

/**
 * An address bound to one concrete transport service.
 */
interface SingleServiceAddressInfo {
    /** Canonical email or E.164 phone number for this participant. */
    readonly address: string;
    /** ISO 3166-1 alpha-2 country code when Messages has one, else omitted. */
    readonly country?: string;
    /** The concrete service this participant record is bound to. */
    readonly service: ChatServiceType;
}
/** A canonical address paired with every service reported by the server. */
interface MultiServiceAddressInfo {
    /** Canonical email or E.164 phone number. */
    readonly address: string;
    /** ISO 3166-1 alpha-2 country code when known, else `null`. */
    readonly country: string | null;
    /** Service set reported by the server. */
    readonly services: readonly ChatServiceType[];
}

/**
 * Message effects and text effects.
 *
 * Apple identifies effects by long reverse-DNS strings. These `as const`
 * objects provide friendly names with full autocomplete and type narrowing --
 * the developer never needs to type (or see) the raw identifiers.
 */
/**
 * Full-screen and bubble effects that can be applied when sending a message.
 *
 * @example
 * ```ts
 * await im.messages.sendText(chat, "Happy birthday!", {
 *   effect: MessageEffect.confetti,
 * });
 * ```
 */
declare const MessageEffect: {
    readonly slam: "com.apple.MobileSMS.expressivesend.impact";
    readonly loud: "com.apple.MobileSMS.expressivesend.loud";
    readonly gentle: "com.apple.MobileSMS.expressivesend.gentle";
    readonly invisible: "com.apple.MobileSMS.expressivesend.invisibleink";
    readonly confetti: "com.apple.messages.effect.CKConfettiEffect";
    readonly fireworks: "com.apple.messages.effect.CKFireworksEffect";
    readonly balloons: "com.apple.messages.effect.CKBalloonEffect";
    readonly heart: "com.apple.messages.effect.CKHeartEffect";
    readonly lasers: "com.apple.messages.effect.CKLasersEffect";
    readonly celebration: "com.apple.messages.effect.CKHappyBirthdayEffect";
    readonly sparkles: "com.apple.messages.effect.CKSparklesEffect";
    readonly spotlight: "com.apple.messages.effect.CKSpotlightEffect";
    readonly echo: "com.apple.messages.effect.CKEchoEffect";
};
/** Union of all valid message-effect ID strings. */
type MessageEffect = (typeof MessageEffect)[keyof typeof MessageEffect];
/**
 * Per-character text effects (iOS 18+) that animate individual words or
 * phrases within a message.
 */
declare const TextEffect: {
    readonly big: "big";
    readonly small: "small";
    readonly shake: "shake";
    readonly nod: "nod";
    readonly explode: "explode";
    readonly ripple: "ripple";
    readonly bloom: "bloom";
    readonly jitter: "jitter";
};
/** Union of all valid text-effect identifier strings. */
type TextEffect = (typeof TextEffect)[keyof typeof TextEffect];

